const resolveMailboxesByLocalParts = `-- name: ResolveMailboxesByLocalParts :many
SELECT company_mailboxes.id, company_mailboxes.company_id, company_mailboxes.local_part, company_mailboxes.created_by_user_id, company_mailboxes.created_at, company_mailboxes.updated_at, company_mailboxes.version
FROM company_mailboxes
JOIN companies
  ON companies.id = company_mailboxes.company_id
 AND companies.deleting_at IS NULL
WHERE company_mailboxes.local_part = ANY($1::text[])
ORDER BY company_mailboxes.id
`

func (q *Queries) ResolveMailboxesByLocalParts(ctx context.Context, localParts []string) ([]CompanyMailbox, error) {
	rows, err := q.db.Query(ctx, resolveMailboxesByLocalParts, localParts)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []CompanyMailbox{}
	for rows.Next() {
		var i CompanyMailbox
		if err := rows.Scan(
			&i.ID,
			&i.CompanyID,
			&i.LocalPart,
			&i.CreatedByUserID,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Version,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

